#!/usr/bin/env bash
set -u
HERE="$(cd "$(dirname "$0")" && pwd)"
RUN="$HERE/../menu_shots/run.sh"
HOST="lua:G.PROFILES[G.SETTINGS.profile].name='ST MORET' bom_match.enter_lobby(true,'AB12') local st=bom_match.get_state() st.visibility='public' st.waiting_guest=true bom_match.update_settings({mode='faceoff',starting_lives=1}) bom_ui.show_lobby()"
BOT="lua:local st=bom_match.get_state() st.waiting_guest=false st.opp_bot=true st.opp_name='Bot-latro Medium' st.opp_ready=true bom_ui.show_lobby()"
GUEST="lua:local st=bom_match.get_state() st.is_host=false st.opp_bot=false st.opp_name='Jimbo' st.visibility='private' bom_ui.show_lobby()"
RK0="{match='a',mode='1v1',result='lose',counted=false,lines={},delta=0,before={rp=0,rank=0,tier=3},after={rp=0,rank=0,tier=3},xp={gain=0,before=0,after=0,levelBefore=1,needBefore=300,need=300},season='2026-11'}"
RK1="{match='b',mode='1v1',result='win',counted=true,lines={{k='placement',v=30},{k='ante',v=12},{k='score',v=6},{k='bots',v=50}},delta=48,before={rp=170,rank=0,tier=2},after={rp=218,rank=0,tier=1},promoted=true,xp={gain=120,before=80,after=200,levelBefore=3,needBefore=400,need=400},season='2026-11'}"
RK2="{match='c',mode='1v1',result='lose',counted=true,lines={{k='placement',v=-10}},delta=-10,before={rp=218,rank=0,tier=1},after={rp=208,rank=0,tier=1},xp={gain=40,before=200,after=240,levelBefore=3,needBefore=400,need=400},season='2026-11',totalPacks=1}"
ONE="lua:bom_ranked.S.games={{result='lose',reason='eliminated',opp='Bot-latro Medium',mode='faceoff',ante=1,ranked=$RK0}} bom_ranked.S.showing=true bom_ranked.show_results()"
ONEW="lua:bom_ranked.S.games={{result='win',reason='opponent_eliminated',opp='Jimbo',mode='nemesis',ante=4,ranked=$RK1}} bom_ranked.S.showing=true bom_ranked.show_results()"
MANY="lua:bom_ranked.S.games={{result='win',reason='opponent_eliminated',opp='Bot-latro Medium',mode='faceoff',ante=3,ranked=$RK1},{result='lose',reason='eliminated',opp='MaximilianTheVeryLongName',mode='nemesis',ante=6,ranked=$RK2},{result='lose',reason='forfeited',opp='Jimbo',mode='ascension',ante=1}} bom_ranked.S.showing=true bom_ranked.show_results()"
NONE="lua:bom_ranked.S.games={{result='win',reason='opponent_abandoned',opp='Jimbo',mode='nemesis',ante=2}} bom_ranked.S.showing=true bom_ranked.request_profile=function() end bom_ranked.show_results()"
S="wait:2|$HOST|wait:1|shot:r01_lobby_host_waiting|$BOT|wait:1|shot:r02_lobby_with_bot|$GUEST|wait:1|shot:r03_lobby_guest"
S="$S|lua:bom_match.reset() if G.OVERLAY_MENU then G.FUNCS.exit_overlay_menu() end|wait:0.5|lua:bom_ranked.request_profile=function() end"
S="$S|$ONE|wait:3|shot:r04_results_unranked|$ONEW|wait:4|shot:r05_results_win|$MANY|wait:4|shot:r06_results_session|$NONE|wait:1|shot:r07_results_no_rank|quit"
[ "${MENU_PART:-all}" = phone ] || bash "$RUN" round plain "$S"
[ "${MENU_PART:-all}" = desktop ] || PHONE=1 SCREEN=1560x720 bash "$RUN" round_phone plain "$S"
